\title{Certified Mordell--Weil Rank Computation\\from Finite Descent Presentations}
\author{Aristotle}
\date{July 30, 2026}
\begin{document}
\maketitle

\begin{abstract}
Let $E/\mathbb Q$ be an elliptic curve. The unconditional computability of the Mordell--Weil rank $r(E)$ for every such curve is not currently known. We isolate the finite linear-algebra endpoint of descent and state exactly what can be computed once a complete certificate is available. For a rational relation matrix $A$ with $n$ rows, set $r_A=n-\rank_{\mathbb Q}(A)$. We prove that $r_A$ is the dimension of $\mathbb Q^n$ modulo the span of the columns of $A$. Whenever a certified descent identifies this quotient with the rationalized free part of $E(\mathbb Q)$, the algebraic rank is exactly $r_A$. Rank parity is transported through the same equality, and any established relation $W(E)=(-1)^{r(E)}$ becomes $W(E)=(-1)^{r_A}$. Exact algorithms, examples, complexity, applications, and the certificate-production gap are discussed.
\end{abstract}

\section{Introduction}
For a nonsingular elliptic curve $E$ over $\mathbb Q$, the Mordell--Weil theorem gives
\[
E(\mathbb Q)\cong \mathbb Z^{r(E)}\oplus E(\mathbb Q)_{\mathrm{tors}},
\]
where the torsion subgroup is finite. The integer $r(E)$ is the algebraic rank. It measures the number of independent points of infinite order and is the algebraic invariant in the Birch and Swinnerton-Dyer conjecture.

Descent methods convert portions of the rank problem into finite calculations. Selmer computations typically give upper bounds, while independent rational points give lower bounds. When these meet, the rank is known. It remains essential to distinguish such successful computations from an unconditional, universally terminating exact-rank algorithm, which is not presently known for all elliptic curves over $\mathbb Q$.

Our contribution is conditional and exact. If arithmetic work supplies a complete finite rational presentation of the rationalized free quotient, then rank computation is ordinary finite-dimensional linear algebra. With $n$ generators and relation rank $\rho$, exactly $n-\rho$ rational directions survive.

\section{Definitions and setup}
\begin{definition}
An \emph{elliptic curve over $\mathbb Q$} is a smooth projective genus-one curve with a rational base point. A short Weierstrass model has the form
\[
E:y^2=x^3+ax+b,
\qquad a,b\in\mathbb Q,
\]
with discriminant $-16(4a^3+27b^2)\ne0$.
\end{definition}
The chord-and-tangent law makes $E(\mathbb Q)$ an abelian group. Its rank is characterized by
\[
E(\mathbb Q)/E(\mathbb Q)_{\mathrm{tors}}\cong\mathbb Z^{r(E)}.
\]
Tensoring with $\mathbb Q$ kills torsion, so the rationalized free part has dimension $r(E)$.

Fix $m,n\ge0$ and a matrix $A\in\operatorname{Mat}_{n\times m}(\mathbb Q)$. Regard its columns as relations in the generator space $\mathbb Q^n$.
\begin{definition}
The relation space and presented quotient are
\[
R_A=\spanQ\{\text{columns of }A\}\subseteq\mathbb Q^n,
\qquad V_A=\mathbb Q^n/R_A.
\]
The \emph{matrix-derived descent rank} is
\[
r_A=n-\rank_{\mathbb Q}(A).
\]
\end{definition}

\begin{definition}
A \emph{complete descent presentation certificate} for $E$ consists, at the level used here, of a rational relation matrix $A$ together with a justified equality
\[
r(E)=\dim_{\mathbb Q}V_A.
\]
An explicit isomorphism from $V_A$ to the rationalized Mordell--Weil group is sufficient.
\end{definition}
The completeness condition matters: a Selmer computation may supply only an upper bound, which cannot automatically be read as the exact rank.

\section{Linear-algebraic foundation}
\begin{lemma}[Relation-rank bound]
For every $A\in\operatorname{Mat}_{n\times m}(\mathbb Q)$,
\[
\rank_{\mathbb Q}(A)\le n.
\]
\end{lemma}
\begin{proof}
The column span is a subspace of the $n$-dimensional space $\mathbb Q^n$, and a subspace cannot have larger dimension than its ambient space.
\end{proof}

\begin{corollary}[Generator--relation identity]
For every such $A$,
\[
r_A+\rank_{\mathbb Q}(A)=n.
\]
\end{corollary}
\begin{proof}
The preceding bound makes the nonnegative subtraction in the definition of $r_A$ valid; cancellation proves the identity.
\end{proof}

\begin{theorem}[Quotient rank--nullity]
For every rational $n\times m$ matrix $A$,
\[
\dim_{\mathbb Q}V_A+\rank_{\mathbb Q}(A)=n.
\]
\end{theorem}
\begin{proof}
For a subspace $R$ of a finite-dimensional vector space $V$,
\[
\dim(V/R)+\dim R=\dim V.
\]
Apply this with $V=\mathbb Q^n$ and $R=R_A$. The dimension of $R_A$ is the column rank of $A$.
\end{proof}

\begin{theorem}[Correctness of the matrix-derived rank]
For every rational $n\times m$ matrix $A$,
\[
r_A=\dim_{\mathbb Q}V_A.
\]
\end{theorem}
\begin{proof}
Both quantities, after addition of $\rank(A)$, equal $n$ by the preceding results. Cancelling the common term proves the claim.
\end{proof}

Elementary row and column operations preserve the relevant quotient dimension: row operations change the generator coordinates by an ambient isomorphism, while invertible column operations change the basis of the relation space. Thus the number depends on the presentation, not its chosen coordinates.

\section{Certified Mordell--Weil rank}
\begin{theorem}[Certified Descent Rank Theorem]
Let $E/\mathbb Q$ be an elliptic curve and let $A$ be a rational $n\times m$ matrix. If a complete descent certificate establishes
\[
r(E)=\dim_{\mathbb Q}V_A,
\]
then
\[
r(E)=r_A=n-\rank_{\mathbb Q}(A).
\]
\end{theorem}
\begin{proof}
The certificate identifies $r(E)$ with $\dim V_A$, and the correctness theorem identifies $\dim V_A$ with $r_A$. Transitivity gives the result.
\end{proof}

\begin{corollary}[Uniqueness across certified presentations]
If $A$ and $B$ are complete descent presentations for the same curve, then
\[
n_A-\rank(A)=n_B-\rank(B).
\]
\end{corollary}
\begin{proof}
Both sides equal $r(E)$.
\end{proof}

This is a certificate-checking paradigm. Constructing the certificate may involve local conditions, Selmer groups, point searches, heights, and repeated descent. Once the asserted quotient is justified, the remaining computation is exact rational linear algebra.

\section{Parity and root numbers}
\begin{theorem}[Parity Transport Theorem]
Under the hypotheses of the Certified Descent Rank Theorem,
\[
r(E)\text{ is even}\quad\Longleftrightarrow\quad r_A\text{ is even},
\]
or equivalently
\[
r(E)\equiv n-\rank(A)\pmod2.
\]
\end{theorem}
\begin{proof}
The two integers are equal, hence have the same residue modulo $2$.
\end{proof}

Let $W(E)\in\{+1,-1\}$ be the root number in the functional equation of the completed $L$-function. The parity conjecture predicts $W(E)=(-1)^{r(E)}$.

\begin{theorem}[Root-number formula from a certified presentation]
Assume a complete presentation and assume, additionally, that
\[
W(E)=(-1)^{r(E)}
\]
holds for $E$. Then
\[
W(E)=(-1)^{r_A}=(-1)^{n-\rank(A)}.
\]
\end{theorem}
\begin{proof}
Substitute the certified equality $r(E)=r_A$ into the assumed parity relation.
\end{proof}

This theorem transports an available parity relation; it does not prove the parity conjecture.

\section{Exact algorithms}
Exact Gaussian elimination computes $\rank(A)$. Search the remaining submatrix for a nonzero pivot, swap rows if necessary, eliminate the pivot column, and advance. The number of pivots is the rank. A dense implementation requires
\[
O\bigl(nm\min(n,m)\bigr)
\]
rational field operations and $O(nm)$ storage. Numerator and denominator growth can be controlled by fraction-free elimination or modular methods, but exact fractions suffice for transparent examples.

The certified endpoint algorithm is:
\begin{enumerate}[label=\arabic*.]
\item Read an $n\times m$ rational relation matrix $A$.
\item Check rectangularity and parse entries exactly.
\item Row-reduce $A$ over $\mathbb Q$.
\item Count pivots to obtain $\rho=\rank(A)$.
\item Return $r_A=n-\rho$ and its parity.
\item If an applicable parity relation is supplied, return $(-1)^{r_A}$.
\end{enumerate}
This matrix phase terminates because each pivot advances through finitely many rows and columns. It does not by itself construct or certify the arithmetic presentation.

For small matrices, minors provide another certificate. A nonzero $k\times k$ minor proves rank at least $k$; vanishing of all $(k+1)\times(k+1)$ minors proves rank at most $k$.

\section{Examples}
\begin{example}[A rank-two quotient]
Let
\[
A_1=\begin{pmatrix}
1&0&1\\0&1&1\\1&1&2\\0&0&0
\end{pmatrix}.
\]
The third column is the sum of the first two, which are independent. Hence $\rank(A_1)=2$ and $r_{A_1}=4-2=2$. A complete presentation by this matrix certifies rank two, even parity, and, under the parity relation, root number $+1$.
\end{example}

\begin{example}[Redundant relations]
Let
\[
A_2=\begin{pmatrix}
1&0&1&2\\0&1&1&2\\0&0&0&0
\end{pmatrix}.
\]
The first two columns are independent; the third is their sum and the fourth twice their sum. Thus $\rank(A_2)=2$ and $r_{A_2}=3-2=1$. Four written columns impose only two independent constraints.
\end{example}

\begin{example}[Boundary cases]
For $A_3=I_3$, one has $\rank(A_3)=3$ and $r_{A_3}=0$. If $A_4$ has $n$ rows and no nonzero columns, then $\rank(A_4)=0$ and $r_{A_4}=n$. Thus the formula handles both complete relations and no relations.
\end{example}

\section{Certificates, applications, and stability}
A practical certificate has three layers. First, it interprets vectors in $\mathbb Q^n$ as rational combinations of proposed generators. Second, it proves that each relation column maps to zero. Third, it proves completeness: every rational relation lies in the column span, or equivalently the induced map from $V_A$ to the rationalized Mordell--Weil group is an isomorphism. Sound relations alone are insufficient for dimension equality.

Exact arithmetic is essential. Columns differing by a rational number with a huge denominator may look identical at fixed precision while remaining independent. Rounding can also destroy an exact dependence. Rational elimination decides whether a pivot is exactly zero.

\begin{proposition}[Stability under redundant relations]
If $B$ is obtained from $A$ by adjoining columns already in $R_A$, then $V_A$ and $V_B$ have equal dimension and $r_A=r_B$.
\end{proposition}
\begin{proof}
The two column spans coincide. Their quotient dimensions therefore coincide, and the correctness theorem gives equal matrix-derived ranks.
\end{proof}

Height pairings provide lower-rank evidence: a nonsingular canonical-height Gram matrix for points $P_1,\ldots,P_k$ proves independence and gives $r(E)\ge k$. Descent supplies upper bounds. When upper and lower bounds meet, the conclusion may be packaged as a complete rank certificate.

The same finite endpoint occurs in homology, finitely presented modules, coding theory, and constrained network models. In each setting, quotienting a generator space by a relation space leaves ``generators minus independent relations'' degrees of freedom.

\section{Scope and future work}
These results do not establish an unconditional algorithm computing $r(E)$ for every elliptic curve over $\mathbb Q$. They establish exact computation from a complete finite descent presentation. Mordell--Weil finite generation does not automatically provide a terminating method to find a full basis. Selmer computations give upper bounds that need not be exact, and point searches give lower bounds that need not be complete.

Future work includes executable fraction-free elimination with checkable traces; richer certificates containing generators, relations, and explicit comparison maps; naive and canonical height theory with Northcott finiteness; concrete $2$-descent, beginning with full rational $2$-torsion; precise hypotheses under which upper and lower bounds meet; and specialization of the root-number transport theorem to local and global elliptic-curve root numbers.

\section{Conclusion}
A complete finite presentation turns Mordell--Weil rank into quotient dimension. For a rational relation matrix $A$ with $n$ rows,
\[
\dim_{\mathbb Q}\bigl(\mathbb Q^n/R_A\bigr)=n-\rank_{\mathbb Q}(A).
\]
If a descent certificate identifies this quotient with the rationalized free part of $E(\mathbb Q)$, the expression is the exact algebraic rank. Its parity is immediate, and any available root-number parity relation becomes an explicit sign formula. Exact linear algebra solves the finite endpoint; the unresolved general challenge is constructing a terminating, complete arithmetic certificate for every curve.

\end{document}

