from fractions import Fraction
from typing import Sequence

def rational_rank(matrix: Sequence[Sequence[int | Fraction]]) -> int:
    a = [[Fraction(x) for x in row] for row in matrix]
    if not a: return 0
    if any(len(row) != len(a[0]) for row in a): raise ValueError("rectangular matrix required")
    r = 0
    for c in range(len(a[0])):
        pivot = next((i for i in range(r, len(a)) if a[i][c]), None)
        if pivot is None: continue
        a[r], a[pivot] = a[pivot], a[r]
        p = a[r][c]
        a[r] = [x / p for x in a[r]]
        for i in range(len(a)):
            if i != r and a[i][c]:
                q = a[i][c]
                a[i] = [x-q*y for x,y in zip(a[i],a[r])]
        r += 1
        if r == len(a): break
    return r


def quotient_report(a: Sequence[Sequence[int | Fraction]]) -> dict[str,int|str]:
    rho=rational_rank(a); r=len(a)-rho
    return {"relation_rank":rho,"quotient_rank":r,"parity":"even" if r%2==0 else "odd","conditional_sign":1 if r%2==0 else -1}

